    .actions{position:fixed;z-index:30;left:50%;bottom:calc(8px + env(safe-area-inset-bottom));transform:translateX(-50%);width:min(calc(100% - 20px),456px);min-height:62px;display:grid;grid-template-columns:1fr 1.2fr 1fr;gap:7px;padding:6px;background:rgba(255,255,255,.94);backdrop-filter:blur(16px);border:1px solid var(--line);border-radius:16px;box-shadow:0 16px 44px rgba(25,48,80,.18)}.action{min-width:0;min-height:48px;border-radius:11px;background:#fff;color:#0873d4;border:1px solid #dce5f0;text-decoration:none;display:flex;align-items:center;justify-content:center;gap:5px;font-size:10px;font-weight:850;cursor:pointer;transition:transform .15s ease,background .15s ease}.action svg{width:16px;height:16px;flex:0 0 16px}.action-wa{color:#119c4b}.action-refresh{color:#0873d4}.action:active{transform:scale(.96);background:#f4f8fc}.action:disabled{opacity:.55}.action-refresh.loading svg{animation:spin .75s linear infinite}.actions.no-phone{grid-template-columns:1fr}
    .state{margin-top:20px;padding:42px 22px;text-align:center}.state-icon{width:66px;height:66px;border-radius:22px;background:var(--blue-soft);color:var(--blue);display:grid;place-items:center;margin:0 auto 15px}.state h1{font-size:19px;margin:0 0 7px}.state p{color:var(--muted);font-size:12px;line-height:1.5;margin:0}.spinner{width:27px;height:27px;border:3px solid #cfe0ef;border-top-color:var(--blue);border-radius:50%;animation:spin .8s linear infinite}.retry{width:100%;min-height:48px;margin-top:17px;border-radius:12px;background:var(--blue-soft);color:var(--blue);font-weight:850;cursor:pointer}
    .hidden{display:none!important}
    @keyframes spin{to{transform:rotate(360deg)}}@keyframes live-pulse{70%{box-shadow:0 0 0 8px transparent}}@keyframes current-pulse{70%{box-shadow:0 0 0 9px transparent}}@keyframes status-float{50%{transform:translateY(-3px) rotate(-2deg)}}@keyframes rise{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}@keyframes step-in{to{opacity:1;transform:none}}@keyframes event-in{from{opacity:0;transform:translateX(-8px)}to{opacity:1;transform:none}}
    @media(min-width:600px){.page{min-height:auto;margin:24px auto;background:#fff;border:1px solid var(--line);border-radius:28px;box-shadow:0 24px 70px rgba(25,48,80,.12)}body{padding-bottom:24px}}
    @media(max-width:350px){.page{padding-left:8px;padding-right:8px}.sheet-card{padding:13px}.status-card{padding:14px;gap:10px}.status-icon{width:50px;height:50px;flex-basis:50px;font-size:24px}.status-title{font-size:17px}.track-label{font-size:7px}.actions{width:calc(100% - 12px);gap:4px}.action{font-size:9px}}
    @media(prefers-reduced-motion:reduce){*{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}
