          <div class="track-step" data-index="4" style="--i:4"><div class="track-dot">5</div><span class="track-label">Finalizare</span></div>
          <div class="track-step" data-index="5" style="--i:5"><div class="track-dot">6</div><span class="track-label">Predare</span></div>
        </div>
