      <section class="recent"><h2 class="recent-heading">Actualizări recente</h2><div class="event"><span class="event-date" id="eventDate">—</span><strong class="event-title" id="eventTitle">Fișa a fost creată</strong><p class="event-description" id="eventDescription"></p></div></section>
      <div class="privacy"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="5" y="10" width="14" height="10" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg><span>Link privat, destinat exclusiv clientului</span></div>
    </div>
  </main>

  <nav class="actions hidden" id="actions" aria-label="Acțiuni rapide"><a id="callButton" class="action"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 16.9v3a2 2 0 0 1-2.2 2A19.8 19.8 0 0 1 3.1 5.2 2 2 0 0 1 5.1 3h3a2 2 0 0 1 2 1.7c.1 1 .4 2 .7 2.9a2 2 0 0 1-.5 2.1L9.1 10.9a16 16 0 0 0 4 4l1.2-1.2a2 2 0 0 1 2.1-.5c.9.3 1.9.6 2.9.7a2 2 0 0 1 1.7 2Z"/></svg>Sună</a><a id="whatsappButton" class="action action-wa" target="_blank" rel="noopener" aria-label="Deschide conversația WhatsApp"><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479s1.065 2.875 1.213 3.074c.149.198 2.095 3.2 5.076 4.487.709.306 1.262.489 1.693.625.712.227 1.36.195 1.872.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.29.173-1.414-.074-.123-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 0 1-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 0 1-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884a9.82 9.82 0 0 1 6.988 2.895 9.825 9.825 0 0 1 2.89 6.99c-.002 5.45-4.437 9.884-9.889 9.884m8.413-18.297A11.815 11.815 0 0 0 12.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 0 0 5.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.82 11.82 0 0 0-3.48-8.413Z"/></svg>WhatsApp</a><button id="refresh" class="action action-refresh" type="button"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 11a8 8 0 1 0-2.3 5.7L20 14"/><path d="M20 5v6h-6"/></svg><span>Reîncarcă</span></button></nav>

  <script>
    const token=<?php echo json_encode($token, JSON_UNESCAPED_SLASHES); ?>;
    const endpoint='./index.php/public/client-form/'+encodeURIComponent(token);
    const STATUS={
      NEW:{label:'Nouă',description:'Dispozitivul a fost înregistrat în sistem.',event:'Fișa de service a fost creată',icon:'📄',color:'#0879db',soft:'#eaf5ff'},
      WAITING:{label:'În așteptare',description:'Dispozitivul așteaptă să fie preluat în service.',event:'Așteaptă preluarea',icon:'⌛',color:'#f09a00',soft:'#fff5e3'},
      VERIFYING:{label:'În verificare',description:'Tehnicianul verifică dispozitivul și identifică problema.',event:'Diagnosticare în desfășurare',icon:'🔍',color:'#7651ad',soft:'#f4effc'},
      IN_PROGRESS:{label:'În lucru',description:'Tehnicianul lucrează în acest moment la dispozitiv.',event:'Reparația a început',icon:'🛠',color:'#0879db',soft:'#eaf5ff'},
      WAITING_PARTS:{label:'Se așteaptă piesele',description:'Piesele necesare au fost comandate.',event:'Piese comandate',icon:'📦',color:'#ef6900',soft:'#fff2e8'},
      COMPLETED:{label:'Finalizată',description:'Dispozitivul este pregătit pentru predare.',event:'Reparația este finalizată',icon:'✓',color:'#15913e',soft:'#edf8ef'},
      DELIVERED:{label:'Predată',description:'Dispozitivul a fost predat clientului.',event:'Dispozitiv predat',icon:'👥',color:'#0b7332',soft:'#edf7f0'},
      CANCELLED:{label:'Anulată',description:'Lucrarea a fost anulată. Contactează unitatea service.',event:'Lucrare anulată',icon:'×',color:'#e43b50',soft:'#fff0f2'}
    };
    const STEP={NEW:0,WAITING:0,VERIFYING:1,IN_PROGRESS:2,WAITING_PARTS:3,COMPLETED:4,DELIVERED:5,CANCELLED:-1};
    const $=id=>document.getElementById(id);const show=id=>$(id).classList.remove('hidden');const hide=id=>$(id).classList.add('hidden');const setText=(id,value)=>{$(id).textContent=value??''};
    const formatDate=(value,withTime=false)=>{if(!value)return '—';const date=new Date(value);if(Number.isNaN(date.getTime()))return '—';const options=withTime?{day:'2-digit',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'}:{day:'numeric',month:'long',year:'numeric'};return new Intl.DateTimeFormat('ro-RO',options).format(date)};
    const whatsappPhone=value=>{let digits=String(value||'').replace(/\D/g,'');if(digits.startsWith('00'))digits=digits.slice(2);if(digits.startsWith('0'))digits='40'+digits.slice(1);return digits};

    function renderProgress(status){const current=STEP[status]??0;const steps=[...document.querySelectorAll('.track-step')];steps.forEach((step,index)=>{step.classList.toggle('reached',current>=0&&index<=current);step.classList.toggle('current',index===current);step.querySelector('.track-dot').textContent=current>=0&&index<=current?'✓':String(index+1)});$('tracker').style.setProperty('--status',STATUS[status]?.color||'#0879db');requestAnimationFrame(()=>{$('trackProgress').style.width=current<0?'0%':(current/(steps.length-1)*100)+'%'})}
    function renderContact(data){const phone=String(data.contact?.phone||'').trim();if(phone){const tel=phone.replace(/[^\d+]/g,'');$('callButton').href='tel:'+tel;const wa=whatsappPhone(phone);$('whatsappButton').href='https://wa.me/'+wa+'?text='+encodeURIComponent('Bună ziua! Vă contactez în legătură cu statusul reparației mele.')}else{$('callButton').classList.add('hidden');$('whatsappButton').classList.add('hidden');$('actions').classList.add('no-phone')}show('actions')}
    function render(data){const repair=data.repair;const current=repair?STATUS[repair.status]:STATUS.NEW;document.documentElement.style.setProperty('--status',current.color);document.documentElement.style.setProperty('--status-soft',current.soft);setText('propertyName',data.propertyName||'Urmărire reparație');document.title='Status reparație · '+(data.propertyName||'G-Shop');setText('sheetNumber',repair?.number||'În curs de creare');setText('equipment',repair?[repair.brand,repair.model,repair.equipment].filter(Boolean).join(' · ')||'Echipament înregistrat':'Fișa de service se pregătește');setText('receivedAt',formatDate(repair?.receivedAt));setText('updatedAt',formatDate(repair?.updatedAt||data.client.updatedAt,true));setText('statusIcon',current.icon);setText('statusLabel',current.label);setText('statusDescription',current.description);setText('eventDate',formatDate(repair?.updatedAt||data.client.updatedAt,true));setText('eventTitle',current.event);setText('eventDescription',current.description);if(repair?.serviceSheetUrl){$('serviceSheetButton').href=repair.serviceSheetUrl;show('serviceSheetButton')}else hide('serviceSheetButton');renderProgress(repair?.status||'NEW');renderContact(data)}
    async function load(){hide('error');const firstLoad=$('content').classList.contains('hidden');if(firstLoad)show('loading');const button=$('refresh');button.disabled=true;button.classList.add('loading');button.querySelector('span').textContent='Se încarcă';try{const response=await fetch(endpoint,{headers:{Accept:'application/json'},cache:'no-store'});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.message||'Statusul nu a putut fi încărcat.');render(payload.data);hide('loading');hide('error');show('content')}catch(error){hide('loading');if(firstLoad){hide('content');hide('actions');show('error');setText('errorText',error.message||'Statusul nu a putut fi încărcat.')}}finally{button.disabled=false;button.classList.remove('loading');button.querySelector('span').textContent='Reîncarcă'}}
    $('refresh').addEventListener('click',load);$('errorRetry').addEventListener('click',load);load();
  </script>
</body>
</html>
